definition:
name: showcase-open-prs-morning
description: Every weekday morning, collect the open pull requests across public tangle-network repositories and compose the Slack digest (delivery step needs a Slack connection)
on:
  schedule: { cron: "0 8 * * 1-5", timezone: UTC }
maxRunCostUsd: 0.5
do:
  - id: prs
    script.run:
      input: { query: "org:tangle-network is:pr is:open", limit: 10 }
      egress: { allowDomains: [api.github.com] }
      timeoutMs: 60000
      source: |
        export default async function run(input: { query: string; limit: number }) {
          const url = "https://api.github.com/search/issues?sort=updated&order=desc&per_page=" + input.limit + "&q=" + encodeURIComponent(input.query);
          const res = await fetch(url, { headers: { accept: "application/vnd.github+json", "user-agent": "tangle-workflow" } });
          if (!res.ok) throw new Error("GitHub search returned " + res.status);
          const body = await res.json();
          const prs = body.items.map((i: any) => ({
            repo: i.repository_url.split("/").slice(-1)[0],
            number: i.number,
            title: i.title,
            draft: !!i.draft,
            url: i.html_url,
            ageDays: Math.floor((Date.now() - Date.parse(i.created_at)) / 86400000),
          }));
          const lines = prs.map((p: any) => "- " + p.repo + "#" + p.number + " " + p.title + (p.draft ? " (draft)" : "") + ", open " + p.ageDays + " d");
          const message = "*Open pull requests* (" + body.total_count + " open, newest activity first)\n" + lines.join("\n");
          console.log(message);
          return { total: body.total_count, prs, message };
        }
